// Normalise every source into one lead object
const src = $prevNode.name;
const j = $json;
let lead = { Date: new Date().toISOString().slice(0,10), Type: 'Enquiry', Status: 'New', FollowUp: new Date(Date.now()+864e5).toISOString().slice(0,10) };
if (src.includes('form')) Object.assign(lead, { Source: 'Website', Customer: j.body?.name, Phone: j.body?.phone, Item: j.body?.message });
else if (src.includes('missed')) Object.assign(lead, { Source: 'Missed call', Customer: 'Missed call', Phone: j.body?.from || j.body?.CallFrom });
else if (src.includes('click')) Object.assign(lead, { Source: 'WA button', Customer: j.query?.page || 'site visitor', Phone: '' });
else { const t = (j.text || j.snippet || ''); Object.assign(lead, { Source: 'Justdial', Customer: (t.match(/Name[:\s]+([^\n,]+)/i)||[])[1] || 'Justdial lead', Phone: (t.match(/(\+?91[\s-]?)?([6-9]\d{9})/)||[])[2] || '', Item: (t.match(/Requirement[:\s]+([^\n]+)/i)||[])[1] || '' }); }
return [{ json: lead }];
